// The painted plates (spec 1.3, 5.5, 6.6): manifest access, hashed URLs, the responsive `<picture>` sources per frame
// and the object-fit: cover math shared by the static picture, the paint-reveal canvas and the live strokes.
// src/assets/plates.json is generated by tools/plates (src/assets/README.md section 1).
import manifest from '../assets/plates.json';
import { FRAMES, FRAME_SIZE, MEDIA, type Frame } from './breakpoints';

export type PlateId =
  'opening' | 'invitation' | 'mehndi' | 'engagement' | 'haldi' | 'wedding' | 'reception' | 'cultures' | 'closing';

export interface StrokeItem {
  /** [x, y, w, h] px in the atlas */
  atlas: number[];
  /** [x, y, w, h] fractions of the frame */
  frame: number[];
  from: number[];
  to: number[];
}

export interface PlateFrame {
  W: number;
  H: number;
  avif: Record<string, string>;
  webp: Record<string, string>;
  lqip: string;
  gold: string;
  veil: string;
  strokes: { file: string; width: number; height: number; items: StrokeItem[] };
  glow?: { x: number; y: number; r: number; k: number };
  couple?: number[];
  floor?: number;
}

export interface PlateEntry {
  palette: string;
  paper: string;
  groundMid: string;
  deep: boolean;
  /** CSS object-position of the painting's focal point */
  focal: string;
  frames: Record<Frame, PlateFrame>;
}

const PLATES = (manifest as unknown as { plates: Record<string, PlateEntry> }).plates;

// URL strings only (no file contents): Vite fingerprints each file and drops the ones nothing references.
const FILES = import.meta.glob('../assets/plates/**/*.{avif,webp}', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

/** The hashed URL of a manifest path (`plates/mehndi/tall-828.avif`). Unknown paths return '' (never throws in render). */
export function plateUrl(rel: string): string {
  return FILES[`../assets/${rel}`] ?? '';
}

export function isPlateId(id: string): id is PlateId {
  return Object.prototype.hasOwnProperty.call(PLATES, id);
}

export function plateEntry(id: string): PlateEntry | undefined {
  return isPlateId(id) ? PLATES[id] : undefined;
}

export const PLATE_IDS = Object.keys(PLATES) as PlateId[];

/** Reduce W/H to the smallest integer ratio (1080/2340 -> 6/13). */
export function ratio(W: number, H: number): string {
  const gcd = (a: number, b: number): number => (b ? gcd(b, a % b) : a);
  const g = gcd(W, H);
  return `${W / g}/${H / g}`;
}

/**
 * `sizes` for a cover-fitted plate (5.5): while the viewport is narrower than the frame's aspect, the painting is
 * scaled by height, so its CSS width is aspect x 100lvh; otherwise it is the viewport width. This makes the browser
 * fetch by the covered width, not just the viewport width.
 */
export function plateSizes(frame: Frame): string {
  const { W, H } = FRAME_SIZE[frame];
  const lvh = Math.round((W / H) * 10000) / 100;
  return `(max-aspect-ratio: ${ratio(W, H)}) ${lvh}lvh, 100vw`;
}

/** `640w`-style srcset from a `{ width: path }` map, smallest first. */
export function srcSet(files: Record<string, string>, url: (rel: string) => string = plateUrl): string {
  return Object.keys(files)
    .map(Number)
    .sort((a, b) => a - b)
    .map((w) => `${url(files[String(w)] ?? '')} ${w}w`)
    .join(', ');
}

export interface PictureSource {
  type: 'image/avif' | 'image/webp';
  media?: string;
  srcSet: string;
  sizes?: string;
}

export interface PlatePicture {
  sources: PictureSource[];
  img: { src: string; width: number; height: number };
  focal: string;
}

/** The media query a frame's `<source>` uses inside the picture (sources are tried in order: tall, mid, wide). */
export function frameSourceMedia(frame: Frame): string | undefined {
  if (frame === 'tall') return MEDIA.tall;
  if (frame === 'mid') return '(max-aspect-ratio: 5/4)';
  return undefined;
}

/** The `<picture>` of a plate's base layer: AVIF then WebP for each frame, the wide 1920 WebP as the `<img>`. */
export function platePicture(id: string): PlatePicture | undefined {
  const p = plateEntry(id);
  if (!p) return undefined;
  const sources: PictureSource[] = [];
  for (const f of FRAMES) {
    const fr = p.frames[f];
    const media = frameSourceMedia(f);
    const sizes = plateSizes(f);
    sources.push({ type: 'image/avif', media, srcSet: srcSet(fr.avif), sizes });
    sources.push({ type: 'image/webp', media, srcSet: srcSet(fr.webp), sizes });
  }
  const wide = p.frames.wide;
  const fallbackW = wide.webp['1920'] ? 1920 : Math.max(...Object.keys(wide.webp).map(Number));
  return {
    sources,
    img: {
      src: plateUrl(wide.webp[String(fallbackW)] ?? ''),
      width: fallbackW,
      height: Math.round((fallbackW * wide.H) / wide.W),
    },
    focal: p.focal,
  };
}

/** A transparent layer drawn on the base's pixel grid (gold leaf or veil): one file per frame, WebP only. */
export function plateLayer(
  id: string,
  layer: 'gold' | 'veil',
): { sources: PictureSource[]; img: { src: string } } | undefined {
  const p = plateEntry(id);
  if (!p) return undefined;
  const sources: PictureSource[] = [];
  for (const f of ['tall', 'mid'] as const) {
    sources.push({ type: 'image/webp', media: frameSourceMedia(f), srcSet: plateUrl(p.frames[f][layer]) });
  }
  return { sources, img: { src: plateUrl(p.frames.wide[layer]) } };
}

/** The pixel size of a plate's wide layer file (gold at the base's 1920 grid, the veil at half that): the <img>'s
 *  width/height attributes (QA r1 T10). */
export function plateLayerSize(id: string, layer: 'gold' | 'veil'): { width: number; height: number } | undefined {
  const p = plateEntry(id);
  if (!p) return undefined;
  const { W, H } = p.frames.wide;
  const k = layer === 'gold' ? 1 : 1280 / 1920;
  return { width: Math.round(W * k), height: Math.round(H * k) };
}

/** The low-quality placeholders as CSS custom properties (the frame's background until the plate decodes, 6.6). */
export function lqipVars(id: string): Record<string, string> {
  const p = plateEntry(id);
  if (!p) return {};
  const out: Record<string, string> = {};
  for (const f of FRAMES) out[`--lqip-${f}`] = `url("${p.frames[f].lqip}")`;
  return out;
}

/**
 * The painted floor line of each frame (fraction of the frame height; event plates only) as `--floor-{frame}`, so
 * the layout can stand the couple on it (layout.css, split events).
 */
export function floorVars(id: string): Record<string, string> {
  const p = plateEntry(id);
  if (!p) return {};
  const out: Record<string, string> = {};
  for (const f of FRAMES) {
    const floor = p.frames[f].floor;
    if (typeof floor === 'number' && floor > 0 && floor < 1) out[`--floor-${f}`] = String(floor);
  }
  return out;
}

/** `<link rel="preload" as="image">` descriptors for a plate (the opening, 6.6), one per frame, AVIF. */
export function platePreloads(id: string): { media: string; imageSrcSet: string; imageSizes: string; type: string }[] {
  const p = plateEntry(id);
  if (!p) return [];
  return FRAMES.map((f) => ({
    media: MEDIA[f],
    imageSrcSet: srcSet(p.frames[f].avif),
    imageSizes: plateSizes(f),
    type: 'image/avif',
  }));
}

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Parse one axis of a CSS object-position (`50%`, `left`, `center`, ...) to a 0..1 fraction. */
function axisFraction(token: string | undefined): number {
  if (!token) return 0.5;
  const t = token.trim().toLowerCase();
  if (t === 'left' || t === 'top') return 0;
  if (t === 'right' || t === 'bottom') return 1;
  if (t === 'center') return 0.5;
  const m = /^(-?\d+(?:\.\d+)?)%$/.exec(t);
  return m ? Number(m[1]) / 100 : 0.5;
}

/**
 * Where an image of `imgW x imgH` lands inside a `boxW x boxH` box under `object-fit: cover` and `object-position:
 * focal` (percentages, as CSS: the free space is split by the percentage). Used by the paint-reveal and the live
 * strokes so a canvas draw and the static `<picture>` coincide to the pixel.
 */
export function coverRect(boxW: number, boxH: number, imgW: number, imgH: number, focal = '50% 50%'): Rect {
  const s = Math.max(boxW / imgW, boxH / imgH);
  const w = imgW * s;
  const h = imgH * s;
  const [fx, fy] = focal.split(/\s+/);
  return { x: (boxW - w) * axisFraction(fx), y: (boxH - h) * axisFraction(fy ?? fx), w, h };
}

/** A rect in frame fractions ([x, y, w, h]: stroke placements, glow points) mapped onto the covered image. */
export function placeOnCover(frac: readonly number[], cover: Rect): Rect {
  const [x = 0, y = 0, w = 0, h = 0] = frac;
  return { x: cover.x + x * cover.w, y: cover.y + y * cover.h, w: w * cover.w, h: h * cover.h };
}
